#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Tool {
    Select,
    Nodes,
    Rect,
    Ellipse,
    Polygon,
    Line,
    Measure,
    Trim,
    Pan,
}

pub struct ToolDef {
    pub tool: Tool,
    pub name: &'static str,
    pub icon: &'static str,
    pub key: &'static str,
    pub hint: &'static str,
}

pub const TOOLS: &[ToolDef] = &[
    ToolDef {
        tool: Tool::Select,
        name: "Select",
        icon: "select",
        key: "S",
        hint: "Click a shape; drag to move it; drag a corner to resize, the round dot to turn (⇧ 15° steps); drag on empty space to box-select",
    },
    ToolDef { tool: Tool::Nodes, name: "Nodes", icon: "dimension", key: "N", hint: "Click a shape, drag its points; double-click a segment to add a point; ⌫ removes the picked point" },
    ToolDef { tool: Tool::Rect, name: "Rectangle", icon: "rect", key: "R", hint: "Drag a rectangle (⇧ square, ⌥ from the centre)" },
    ToolDef { tool: Tool::Ellipse, name: "Ellipse", icon: "circle", key: "E", hint: "Drag an ellipse (⇧ circle, ⌥ from the centre)" },
    ToolDef { tool: Tool::Polygon, name: "Polygon", icon: "polygon", key: "O", hint: "Drag from the centre out to a corner (⇧ 15° turns); sides and star in the Polygon box" },
    ToolDef { tool: Tool::Line, name: "Line", icon: "line", key: "L", hint: "Click points (⇧ 15° steps); click the first point or press Enter to finish, Esc to drop it" },
    ToolDef { tool: Tool::Measure, name: "Measure", icon: "tape", key: "M", hint: "Drag between two points for the distance; point at a shape for its size, outline and area" },
    ToolDef { tool: Tool::Trim, name: "Trim", icon: "trim", key: "K", hint: "Click a line between two crossings: that stretch is cut away (nothing crosses = the shape goes)" },
    ToolDef { tool: Tool::Pan, name: "Pan", icon: "pan", key: "H", hint: "Drag to move the view; the wheel zooms" },
];

fn def(t: Tool) -> &'static ToolDef {
    TOOLS.iter().find(|d| d.tool == t).unwrap()
}

#[derive(Clone, Debug)]
enum Stage {
    Idle,
    /// dragging guide `idx` (out of a ruler, or an existing one); dropped on a ruler = removed
    Guide {
        idx: usize,
    },
    /// rectangle / ellipse from the press point
    Draw {
        from: Pt,
    },
    /// the Line tool's points so far: a click = a corner, a click-and-drag = a smooth point whose handle is the drag
    /// (`handles[i]` = the leaving handle as an offset from `pts[i]`; the arriving one mirrors it)
    Line {
        pts: Vec<Pt>,
        handles: Vec<Option<Pt>>,
        dragging: bool,
    },
    /// moving the selection (world point of the last frame; did it move at all)
    Move {
        last: Pt,
        moved: bool,
        /// where the drag began and the selection's box then (the whole move is measured from them, so alignment
        /// snaps don't drift)
        start: Pt,
        was: gburn_core::Rect,
    },
    /// resizing the selection from a corner: the fixed opposite corner and the box at the press
    Scale {
        anchor: Pt,
        from: Pt,
    },
    /// turning the selection about its centre with the handle above its box: the angle at the press and how far
    /// it has turned so far (radians)
    Rotate {
        centre: Pt,
        a0: f64,
        done: f64,
    },
    /// dragging node `idx` of shape `id` (Nodes tool)
    Node {
        id: i32,
        idx: usize,
        moved: bool,
    },
    Measure {
        a: Pt,
    },
    SelBox {
        from: Pt,
    },
    /// Two-point rotate / scale: the pivot (first click), then the point being dragged round it
    TwoPoint {
        pivot: Option<Pt>,
        from: Option<Pt>,
    },
    Pan {
        last: Pos2,
    },
}

/// Machine numbers kept on this device (store key `machine`).
#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct MachineSettings {
    pub bed: [f64; 2],
    pub rapid: f64,
    pub accel: f64,
    /// time estimate: fills' / pictures' acceleration (0 = the same), each axis's top speed mm/s (0 = none)
    #[serde(default)]
    pub accel_fill: f64,
    #[serde(default)]
    pub max_xy: [f64; 2],
    /// time estimate: GRBL $11 junction deviation mm (0 = corners free)
    #[serde(default = "corner_dev_default")]
    pub corner_dev: f64,
    /// 0 = take $30 from the controller
    pub s_max: f64,
    pub baud: u32,
    pub dynamic: bool,
    /// 0 = absolute coordinates, 1 = start from the head's current position (the job origin point stands there)
    #[serde(default)]
    pub start_from: u8,
    /// job origin for "current position": 0..9 = bottom-left, bottom-centre, bottom-right, left, centre, right, top-left, top-centre, top-right
    #[serde(default)]
    pub origin: u8,
    /// Ruida: the controller's address and which bed corner it homes to
    #[serde(default = "default_ip")]
    pub ruida_ip: String,
    /// the job origin is taken from the selection's box (Use selection origin)
    #[serde(default)]
    pub sel_origin: bool,
    /// GRBL over the network: "host" or "host:port" (Telnet 23)
    #[serde(default)]
    pub grbl_net: String,
    #[serde(default)]
    pub home: gburn_core::ruida::Home,
    /// the Fire button (a short low-power pulse to find the focus / the spot): off unless switched on here
    #[serde(default)]
    pub fire: bool,
    #[serde(default = "ten")]
    pub fire_power: f64,
    /// rotary attachment on Y: mm of Y travel per full turn, and the object's diameter (mm)
    #[serde(default)]
    pub rotary: bool,
    /// G-code: the rotary is its own A axis (degrees) instead of standing in for Y
    #[serde(default)]
    pub rotary_a: bool,
    #[serde(default = "hundred")]
    pub mm_per_rot: f64,
    #[serde(default = "fifty")]
    pub diameter: f64,
    /// Taper warp for a tapered tumbler on the rotary: its diameter at the design's left and right ends (0 = off)
    #[serde(default)]
    pub taper: [f64; 2],
    /// show speeds in mm/min (diode-laser habit) instead of mm/s
    #[serde(default)]
    pub per_min: bool,
    /// job times are multiplied by this (match the estimate to what the machine really takes)
    #[serde(default = "one_f64")]
    pub time_factor: f64,
    /// saved head positions (Laser tab › Spots), mm
    #[serde(default)]
    pub spots: Vec<[f64; 2]>,
    /// galvo: lens field, source, flips (the correction file is store key `cor`, base64)
    #[serde(default)]
    pub galvo: gburn_core::galvo::GalvoOptions,
    /// Frame follows the design's outline (convex hull) instead of its box
    #[serde(default)]
    pub frame_hull: bool,
    /// a red-dot pointer this far from the beam (mm, pointer − beam): Frame moves the head so the dot traces the design
    #[serde(default)]
    pub pointer_offset: [f64; 2],
    /// Frame repeats until Stop (GRBL / Ruida; the galvo's red light always does)
    #[serde(default)]
    pub frame_loop: bool,
    /// GRBL: frame with the beam on at this % (diodes without a red dot), 0 = off, at most 5
    #[serde(default)]
    pub frame_power: f64,
    /// home the machine right after connecting
    #[serde(default)]
    pub home_on_connect: bool,
    /// G0 X0 Y0 after a GRBL job
    #[serde(default = "yes")]
    pub home_after: bool,
    /// … to this spot (mm; bed coordinates)
    #[serde(default)]
    pub finish: [f64; 2],
    /// past this (0 = never) the serial number goes back to `serial_start`
    #[serde(default)]
    pub serial_end: u32,
    #[serde(default = "one_u32")]
    pub serial_start: u32,
    /// the serial number goes up by this after each Start
    #[serde(default = "one_u32")]
    pub serial_step: u32,
    /// the next `{n}` for variable text (goes up by one after each Start)
    #[serde(default = "one_u32")]
    pub serial: u32,
    /// cut order: shortest travel (nearest first, holes first) or as drawn
    #[serde(default = "yes")]
    pub optimize: bool,
    /// Line layers: shared edges cut once (plan::remove_overlaps)
    #[serde(default)]
    pub remove_overlap: bool,
    /// each group gets all its layers before the next (plan::Machine.by_group)
    #[serde(default)]
    pub by_group: bool,
    /// closed shapes start at a sharp corner (plan::Machine.corners)
    #[serde(default)]
    pub corners: bool,
    /// plan::Machine { sweep, fewer_turns, backlash }: direction order, reduce direction changes, hide backlash
    #[serde(default)]
    pub sweep: u8,
    #[serde(default)]
    pub fewer_turns: bool,
    #[serde(default)]
    pub backlash: bool,
    /// GRBL scanning offset: (speed mm/s, mm) rows (gcode::scan_offset_at)
    #[serde(default)]
    pub scan_offsets: Vec<(f64, f64)>,
    /// GRBL: lines sent before / after every job
    #[serde(default)]
    pub gcode_start: String,
    #[serde(default)]
    pub gcode_end: String,
    /// LightBurn's job checklist: one item a line, every one ticked before Start goes (empty = off)
    #[serde(default)]
    pub checklist: String,
    /// S on every G1 (some controllers need it)
    #[serde(default)]
    pub s_every: bool,
    /// GRBL: synchronous transfer (a line at a time) instead of filling the controller's buffer
    #[serde(default)]
    pub sync_stream: bool,
    /// the G-code controller: 0 GRBL / grblHAL / FluidNC, 1 Smoothieware, 2 Marlin, 3 RepRapFirmware, 4 Snapmaker,
    /// 5 Marlin with the laser on the fan pin (2–5 use Marlin's conversation: M114, G28, M410)
    #[serde(default)]
    pub controller: u8,
    /// the stock's thickness, mm, for machines that focus by Z from the job (the xTool M1)
    #[serde(default)]
    pub thickness: f64,
    /// a Ruida with two laser heads: each layer picks laser 1, laser 2 or both (Cut settings › Laser head)
    #[serde(default)]
    pub dual_head: bool,
    /// G-code: air assist on M7 instead of M8
    #[serde(default)]
    pub air_m7: bool,
    /// G-code: X and Y swapped on the way out; fills' / pictures' blank moves as G0
    #[serde(default)]
    pub swap_xy: bool,
    #[serde(default)]
    pub blank_g0: bool,
    /// G-code: M73 progress lines (machines with a screen)
    #[serde(default)]
    pub m73: bool,
    /// GRBL: the corner the machine calls 0,0 (0 front-left, 1 rear-left, 2 front-right, 3 rear-right)
    #[serde(default)]
    pub grbl_origin: u8,
    /// arrow keys jog the laser (by the Laser tab's step) when nothing is selected
    #[serde(default)]
    pub arrow_jog: bool,
    /// GRBL console buttons: (name, lines)
    #[serde(default)]
    pub macros: Vec<(String, String)>,
}

