/// A saved cut setting (Materials): what a layer copies in.
#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct Preset {
    /// the description ("through cut")
    pub name: String,
    pub mode: Mode,
    pub speed: f64,
    pub power: f64,
    pub passes: u32,
    pub interval: f64,
    /// LightBurn's grouping: material › thickness (mm)
    #[serde(default)]
    pub material: String,
    #[serde(default)]
    pub thickness: String,
    /// the whole layer setting when saved here (kerf, dither, air…); .clb imports have only the numbers above
    #[serde(default)]
    pub layer: Option<gburn_core::Layer>,
}

impl Preset {
    /// "Birch ply · 3 mm · through cut"
    pub fn label(&self) -> String {
        let t = if self.thickness.trim().is_empty() || self.thickness.trim() == "-1" { String::new() } else { format!("{} mm", self.thickness.trim()) };
        [self.material.as_str(), t.as_str(), self.name.as_str()].iter().filter(|s| !s.is_empty()).cloned().collect::<Vec<_>>().join(" · ")
    }
    fn clb(&self) -> gburn_core::text::ClbEntry {
        let kind = match self.mode {
            Mode::Line => "Cut",
            Mode::Image => "Image",
            _ => "Scan",
        };
        gburn_core::text::ClbEntry {
            name: self.label(),
            material: if self.material.is_empty() { "GBurn".into() } else { self.material.clone() },
            thickness: self.thickness.clone(),
            desc: self.name.clone(),
            kind: kind.into(),
            speed: self.speed,
            power: self.power,
            passes: self.passes,
            interval: self.interval,
        }
    }
}

/// Camera overlay: the last photo (grey, row 0 at the top), its texture, the four marks clicked on it (photo px) and
/// the bed points they are (typed, mm)
#[derive(Default)]
pub struct CamState {
    photo: Option<(usize, usize, Vec<u8>)>,
    tex: Option<egui::TextureHandle>,
    marks: [Option<Pt>; 4],
    bed: [[String; 2]; 4],
    /// the lens's barrel bend (raster::lens_bend; − = barrel)
    bend: f64,
}

impl CamState {
    /// the alignment kept from last time (store key `camalign`), else the bed's corners
    fn load(saved: Option<String>, bed: [f64; 2]) -> CamState {
        let v: serde_json::Value = saved.and_then(|s| serde_json::from_str(&s).ok()).unwrap_or_default();
        let p = |v: &serde_json::Value| Some(pt(v.get(0)?.as_f64()?, v.get(1)?.as_f64()?));
        let corners = [pt(0.0, 0.0), pt(bed[0], 0.0), pt(bed[0], bed[1]), pt(0.0, bed[1])];
        let mut c = CamState { bend: v["bend"].as_f64().unwrap_or(0.0), ..Default::default() };
        for (k, corner) in corners.iter().enumerate() {
            c.marks[k] = v["marks"].get(k).and_then(p);
            let b = v["bed"].get(k).and_then(p).unwrap_or(*corner);
            c.bed[k] = [trim(b.x, 1), trim(b.y, 1)];
        }
        c
    }
}

/// the saved art: names and outlines (pictures aren't kept)
fn load_art(saved: Option<String>) -> Vec<(String, Vec<Contour>)> {
    let list: Vec<(String, String)> = saved.and_then(|s| serde_json::from_str(&s).ok()).unwrap_or_default();
    list.into_iter().filter_map(|(n, j)| Document::from_json(&j).ok().map(|d| (n, d.shapes.into_iter().map(|s| s.contour).collect()))).collect()
}

/// does the outline touch the box: a point of it inside, or a segment crossing an edge
/// A closed outline that is a circle (within 2 %): its centre and radius.
fn circle_of(c: &Contour) -> Option<(Pt, f64)> {
    let b = bounds(c);
    let r = (b.w() + b.h()) / 4.0;
    if !c.closed || r < 1e-6 || (b.w() - b.h()).abs() > 0.01 * r.max(1.0) {
        return None;
    }
    let cen = pt((b.x0 + b.x1) / 2.0, (b.y0 + b.y1) / 2.0);
    flatten(c, 0.02).iter().all(|p| (geom::dist(*p, cen) - r).abs() < 0.02 * r + 0.02).then_some((cen, r))
}

fn touches(c: &Contour, r: &gburn_core::Rect) -> bool {
    let b = bounds(c);
    if b.x1 < r.x0 || b.x0 > r.x1 || b.y1 < r.y0 || b.y0 > r.y1 {
        return false;
    }
    let mut pts = flatten(c, 0.05);
    if c.closed {
        if let Some(&f) = pts.first() {
            pts.push(f);
        }
    }
    let inside = |p: &Pt| p.x >= r.x0 && p.x <= r.x1 && p.y >= r.y0 && p.y <= r.y1;
    if pts.iter().any(inside) {
        return true;
    }
    // a segment through the box: it crosses one of the box's sides
    let cross = |a: Pt, b: Pt, c: Pt, d: Pt| {
        let o = |p: Pt, q: Pt, r: Pt| (q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x);
        (o(a, b, c) > 0.0) != (o(a, b, d) > 0.0) && (o(c, d, a) > 0.0) != (o(c, d, b) > 0.0)
    };
    let corners = [pt(r.x0, r.y0), pt(r.x1, r.y0), pt(r.x1, r.y1), pt(r.x0, r.y1)];
    pts.windows(2).any(|w| (0..4).any(|k| cross(w[0], w[1], corners[k], corners[(k + 1) % 4])))
}

/// the fill shading's scanlines per layer colour
type FillShade = Vec<([u8; 3], Vec<[Pt; 2]>)>;

/// each kerfed layer's offset paths, for the dashed preview
type KerfPaths = Vec<(usize, Vec<Contour>)>;

/// A new layer for palette colour `k`; on a galvo (fibre) a marking speed and power instead of a gantry's cut
fn new_layer(k: usize, galvo: bool) -> gburn_core::Layer {
    let mut l = gburn_core::default_layer(k);
    if galvo {
        (l.speed, l.power, l.freq_khz, l.interval) = (1000.0, 30.0, 30.0, 0.05);
    }
    l
}

/// `l` gets every cut setting of `from`, keeping what makes it this layer (name, colour, output, shown, sub-layers)
const UI_SCALES: [u32; 5] = [90, 100, 115, 130, 150];

fn take_settings(l: &mut gburn_core::Layer, from: &gburn_core::Layer) {
    let keep = (l.name.clone(), l.color, l.output, l.visible, std::mem::take(&mut l.subs), std::mem::take(&mut l.link));
    *l = from.clone();
    (l.name, l.color, l.output, l.visible, l.subs, l.link) = keep;
}

/// A Material Library entry onto a layer, which then follows it (`link`)
fn apply_preset(l: &mut gburn_core::Layer, p: &Preset) {
    if let Some(full) = &p.layer {
        take_settings(l, full);
    }
    (l.mode, l.speed, l.power, l.passes, l.interval) = (p.mode, p.speed, p.power, p.passes, p.interval);
    l.link = p.label();
}

