            m.item("Choose Your Machine…", "", !connected, "machinedb");
            m.sep();
            m.item("Print & Cut…", "", !empty, "printcut");
            m.item("Run a G-code File…", "", !running, "rungcode");
            m.item("Material Library…", "", true, "matlib");
            m.item("Import Material Library (.clb)…", "", true, "clb");
