impl eframe::App for App {
    #[cfg(not(target_arch = "wasm32"))]
    fn on_exit(&mut self, _gl: Option<&eframe::glow::Context>) {
        self.laser.disconnect();
        if std::env::var_os("GBURN_SHOT").is_none() {
            recover::clear();
        }
    }

    fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {
        let ctx = ui.ctx().clone();
        crate::i18n::fonts(&ctx, &self.lang);
        gcarve_ui::cloud::set_reports(!self.prefs.no_reports); // Settings › Send problem reports (any change, an import)
        let zoom = self.ui_scale as f32 / 100.0;
        if (ctx.zoom_factor() - zoom).abs() > 0.001 {
            ctx.set_zoom_factor(zoom);
        }
        self.frame += 1;
        let t = now(&ctx);
        let dt = (t - self.t_last).clamp(0.0, 0.25);
        self.t_last = t;
        self.t_now = t;
        #[cfg(not(target_arch = "wasm32"))]
        self.automation_poll(&ctx);
        // `web_opening`: the browser's port chooser is up or the port is being opened; tick picks the result up (it only
        // ran once connected, so a Web Serial port that opened was never noticed, 2026-10-24)
        if self.laser.connected() || self.laser.opening() {
            if self.laser.opening() {
                ctx.request_repaint_after(std::time::Duration::from_millis(100));
            }
            self.laser.marlin = (2..XTOOL).contains(&self.machine.controller);
            self.laser.xtool = self.machine.controller >= XTOOL;
            self.laser.f1 = self.machine.controller >= XTOOL_F1;
            self.laser.f1_ir = self.machine.controller > XTOOL_F1;
            self.laser.mirror = if self.laser.is_gcode() { self.grbl_mirror() } else { [None, None] };
            // the Ruida link maps jogs and frames with the machine's current bed and home corner (Use it, Machine Settings)
            let (bed, home, rapid) = (self.machine.bed, self.machine.home, self.machine.rapid);
            if let Some(r) = self.laser.ruida.as_mut() {
                (r.opts.bed, r.opts.home, r.move_speed) = (bed, home, rapid.clamp(10.0, 300.0));
            }
            self.laser.swap = self.laser.is_gcode() && self.machine.swap_xy && !self.machine.rotary_a;
            self.laser.tick(t, dt);
            #[cfg(not(target_arch = "wasm32"))]
            if let Some((pin, since)) = self.light_probe {
                ctx.request_repaint_after(std::time::Duration::from_millis(200));
                if t - since > 2.5 {
                    let next = pin + 1;
                    if next > 15 {
                        if let Some(g) = self.laser.galvo.as_mut() {
                            g.probe_pin(None);
                        }
                        self.light_probe = None;
                        self.status = "No pin lit the red pointer (1–15). Does the machine have one?".into();
                    } else {
                        if let Some(g) = self.laser.galvo.as_mut() {
                            g.probe_pin(Some(next));
                        }
                        self.light_probe = Some((next, t));
                        self.status = format!("Trying pin {next} for the red pointer: press Stop when the dot shows");
                    }
                }
            }
            if let Some(a) = self.laser.alert.take() {
                self.status = a;
            }
            self.report_problem();
            // hold to move: let go = stop
            if self.jog_holding && !ctx.input(|i| i.pointer.any_down()) {
                self.jog_holding = false;
                self.laser.jog_cancel();
            }
            ctx.request_repaint_after(std::time::Duration::from_millis(50));
            if self.home_at.is_some_and(|at| t >= at) {
                self.home_at = None;
                if !self.laser.is_galvo() && matches!(self.laser.job_state(), laser::Job::None) {
                    self.laser.home();
                    self.status = "Homing (Machine Settings › Home when connecting)".into();
                }
            }
            if self.frame_next.is_some_and(|at| t >= at) {
                self.frame_next = None;
                if matches!(self.laser.job_state(), laser::Job::None | laser::Job::Done) {
                    self.pending_cmd = Some("frame".into());
                }
            }
        } else {
            self.frame_next = None;
            self.home_at = None;
        }
        self.keys(&ctx);
        self.files_in(&ctx);
        self.phone = ui.ctx().content_rect().width() < 600.0;
        if !std::mem::replace(&mut self.phone_init, true) && ui.ctx().content_rect().width() < 600.0 && store::load("sidehidden").is_none() {
            self.side_hidden = true;
        }
        self.menu_bar(ui);
        self.mode_bar(ui);
        self.status_bar(ui);
        self.toolbar(ui);
        self.side_panel(ui);
        egui::CentralPanel::default().frame(egui::Frame::new()).show(ui, |ui| {
            if !self.preview && !self.phone {
                self.tool_options(ui);
            }
            self.canvas(ui)
        });
        if self.preview {
            self.sim_bar(&ctx);
            self.sim_legend_box(&ctx);
        }
        if let Some(c) = self.pending_cmd.take() {
            self.run(&ctx, &c);
        }
        self.dialogs(&ctx);
        if self.palette.open {
            let cmds = self.commands();
            if let Some(id) = self.palette.ui(&ctx, &cmds, "Type a command… e.g. preview, frame, text, layer") {
                self.run(&ctx, &id);
            }
        }
        self.account_tick(&ctx);
        #[cfg(all(feature = "screenshot", not(target_arch = "wasm32")))]
        gcarve_ui::shot::tick(&ctx, self.frame);
        #[cfg(target_arch = "wasm32")]
        self.smoke(&ctx);
    }
}

#[cfg(target_arch = "wasm32")]
impl App {
    /// `?smoke`: run the script after a few frames and report to the page's server (smoke-web.sh reads its log).
    fn smoke(&mut self, ctx: &egui::Context) {
        if !smoke_requested() || self.frame > 40 {
            return;
        }
        ctx.request_repaint();
        if self.frame != 30 {
            return;
        }
        let mut a = App::headless();
        a.view = self.view;
        let msg = match a.script_check().and_then(|s| a.press_everything().map(|p| format!("{s}, {p}"))) {
            Ok(s) => format!("SMOKE OK {s}"),
            Err(e) => format!("SMOKE FAIL {e}"),
        };
        web_sys::console::log_1(&msg.clone().into());
        if let Some(w) = web_sys::window() {
            let origin = w.location().origin().unwrap_or_default();
            let _ = w.fetch_with_str(&format!("{origin}/smoke-result?{}", msg.replace(' ', "+").replace(',', "")));
        }
    }
}

