/// a Boolean Assistant tile: (name, command, result)
type BoolPreview = (&'static str, &'static str, Vec<Contour>);

/// Settings › the smaller switches (store `prefs`)
#[derive(Clone, Copy, Debug, Default, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(default)]
struct Prefs {
    /// stay on the drawing tool after a shape (off = back to Select, so the next drag moves what was just drawn;
    /// owner 2026-11-24: "made a square and it would not move by me clicking and dragging")
    keep_tool: bool,
    /// lines across the whole canvas through the pointer
    crosshair: bool,
    /// a cross at the bed's centre
    centre_cross: bool,
    /// an import arrives as one group / in the middle of the bed
    import_group: bool,
    import_centre: bool,
    /// a line per Start in the job log (store `jobs`)
    job_log: bool,
    /// Beginner mode: the cut settings show only the basics
    beginner: bool,
    /// listen on 127.0.0.1:19840 for other programs (LightBurn's UDP commands: PING, STATUS, LOADFILE, FORCELOAD,
    /// IMPORT, LASER, CLOSE, FORCECLOSE)
    automation: bool,
    /// no review card before Start
    #[serde(default)]
    skip_review: bool,
    /// …and let them START a job (off by default: Start is otherwise always a click here)
    #[serde(default)]
    automation_start: bool,
    /// LightBurn's Show Last Position: where the head last was, marked once the laser is gone
    last_pos: bool,
    /// how close the pointer must be to pick a shape / snap to a point, px (0 = 6 / 8)
    pick_px: f32,
    snap_px: f32,
    /// the top bar's ♥ donate button is hidden (right-click it, or Settings › General; Help › Donate stays)
    hide_donate: bool,
    /// Settings › General › Send problem reports, off: nothing goes to the shared error log (owner 2026-11-20; on by default)
    no_reports: bool,
    /// the one-time Problem reports card was seen (owner 2026-11-22: tell people what is sent, let them opt out / delete)
    data_seen: bool,
}

impl Prefs {
    fn pick_px(&self) -> f64 {
        if self.pick_px > 0.0 {
            self.pick_px as f64
        } else {
            6.0
        }
    }
    fn snap_px(&self) -> f64 {
        if self.snap_px > 0.0 {
            self.snap_px as f64
        } else {
            8.0
        }
    }
}

/// Overscan that lets the head reach `speed` (mm/s) at `accel` (mm/s²) before the burn starts: v² / 2a + 10 %
fn auto_overscan(speed: f64, accel: f64) -> f64 {
    ((speed * speed / (2.0 * accel.max(1.0)) * 1.1 * 10.0).ceil() / 10.0).clamp(0.0, 20.0)
}

/// A test label's outlines (the built-in font), `h` mm tall, bottom left at (x, y)
fn label_at(text: &str, h: f64, x: f64, y: f64) -> Vec<Contour> {
    let m = Affine::scale(MM_PER_IN, MM_PER_IN);
    let cs: Vec<Contour> = gcarve_ui::glyphs::text_outlines(text, h / MM_PER_IN, false).iter().map(|c| transformed(c, &m)).collect();
    let mut b = gburn_core::Rect::default();
    for c in &cs {
        b.add_rect(&bounds(c));
    }
    if b.is_empty() {
        return Vec::new();
    }
    let mv = Affine::translate(x - b.x0, y - b.y0);
    cs.iter().map(|c| transformed(c, &mv)).collect()
}

/// a key with its modifiers, Mac style (⌃⌥⇧⌘ then the key): `theme::keys` shows it as Ctrl+… elsewhere
fn combo_text(k: Key, m: egui::Modifiers) -> String {
    let mut s = String::new();
    if m.mac_cmd && m.ctrl {
        s.push('⌃'); // the Mac's Control (⌘ is `command` everywhere)
    }
    if m.alt {
        s.push('⌥');
    }
    if m.shift {
        s.push('⇧');
    }
    if m.command {
        s.push('⌘');
    }
    s + k.symbol_or_name()
}

