/// Every vector format the importers read (file pickers).
/// Time left in a job `f` done (0–1) after `elapsed` s: the plan's estimate at first, then more and more the pace so far.
fn time_left(f: f64, elapsed: f64, estimate: f64) -> f64 {
    let f = f.clamp(0.0, 1.0);
    let by_plan = estimate * (1.0 - f);
    if f < 0.02 {
        return by_plan;
    }
    let by_pace = elapsed * (1.0 - f) / f;
    let w = (f / 0.2).min(1.0); // trust the pace fully from 20 % on
    by_plan * (1.0 - w) + by_pace * w
}

/// Copies made by an array count up: their variable texts and codes show serial / CSV row + `k` (LightBurn's Offset)
fn count_up(d: &mut Document, ids: &[i32], k: u32) {
    for s in d.shapes.iter_mut().filter(|s| k > 0 && ids.contains(&s.id)) {
        if let Some(t) = s.text.as_mut().filter(|t| t.has_vars()) {
            t.offset += k;
        }
        if let Some(c) = s.code.as_mut().filter(|c| c.has_vars()) {
            c.offset += k;
        }
    }
}

/// A settings row's name in the side panel: a fixed column that wraps a long name (other languages) onto a second
/// line instead of widening the page
fn row_label(ui: &mut egui::Ui, text: &str) {
    ui.scope(|ui| {
        ui.set_max_width(ROW_LABEL_W);
        ui.add(egui::Label::new(text).wrap());
    });
}
const ROW_LABEL_W: f32 = 96.0;

/// A row name in a dialog laid out in rows (not a grid): a fixed column, so the boxes after it line up
fn text_label(ui: &mut egui::Ui, text: &str) {
    ui.scope(|ui| {
        ui.set_width(ROW_LABEL_W);
        ui.add(egui::Label::new(text).wrap());
    });
}

/// One menu's items drawn in the window's bar.
fn menu_nodes(ui: &mut egui::Ui, nodes: &[Node], cmd: &mut Option<String>) {
    for n in nodes {
        match n {
            Node::Item { label, key, on, id } => {
                if ui.add_enabled_ui(*on, |ui| widgets::menu_item(ui, tr(label), key)).inner.clicked() {
                    *cmd = Some(id.clone());
                    ui.close();
                }
            }
            Node::Sep => widgets::menu_separator(ui),
            Node::Sub { label, on, items } => {
                ui.add_enabled_ui(*on, |ui| widgets::submenu(ui, tr(label), |ui| menu_nodes(ui, items, cmd)));
            }
        }
    }
}

fn vector_exts() -> Vec<&'static str> {
    ["svg", "dxf", "lbrn2", "lbrn", "pdf", "ai", "eps", "plt", "hpgl"].into_iter().chain(gburn_core::GERBER_EXTS).chain(gburn_core::DRILL_EXTS).chain(gburn_core::GCODE_EXTS).collect()
}

